export default async function ({ body }, ctx) {
  if (
    typeof body?.messageId !== "string" ||
    !body.messageId ||
    typeof body?.fileId !== "string" ||
    !body.fileId
  )
    throw Error("Missing message or uploaded file ID");
  const key = "invoice-llama:" + body.messageId,
    s = await ctx.state.get(key);
  if (s?.fileId && s.fileId !== body.fileId) throw Error("Different file ID for existing message");
  if (s?.phase === "job-pending" || s?.phase === "row-pending" || s?.phase === "label-pending")
    throw Error("Inspect unknown external result before retry");
  if (s?.phase === "done") return { key, mode: "done", jobId: s.jobId, body: null };
  if (s?.phase === "row-done") return { key, mode: "label", jobId: s.jobId, body: null };
  if (s?.jobId) return { key, mode: "poll", jobId: s.jobId, body: null };
  await ctx.state.set(key, { phase: "job-pending", fileId: body.fileId });
  return {
    key,
    mode: "create",
    jobId: "",
    body: { file_id: body.fileId, tier: "agentic", version: "latest" },
  };
}

