export default async function ({ key }, ctx) {
  const s = await ctx.state.get(key),
    id = s?.jobId;
  if (!/^[A-Za-z0-9_-]+$/.test(id ?? "")) throw Error("Invalid parse job ID");
  return {
    jobId: id,
    url: "https://api.cloud.llamaindex.ai/api/v2/parse/" + id + "?expand=markdown",
  };
}

