export default function ({ response, jobId }) {
  const s = response?.job?.status;
  if (["PENDING", "RUNNING"].includes(s)) return { ready: false, markdown: "", jobId };
  if (s !== "COMPLETED") throw Error("LlamaParse failed or returned unknown status");
  const p = response?.markdown?.pages;
  if (
    !Array.isArray(p) ||
    !p.length ||
    p.some((x) => x.success !== true || typeof x.markdown !== "string")
  )
    throw Error("Incomplete parsed invoice");
  return { ready: true, markdown: p.map((x) => x.markdown).join("\n\n"), jobId };
}

