export default async function ({ key, invoice }, ctx) {
  const s = await ctx.state.get(key);
  if (!s?.jobId) throw Error("Missing parse job");
  if (s.phase === "row-pending") throw Error("Inspect sheet before retry");
  if (s.phase === "row-done" || s.phase === "done") return { skip: true, values: [] };
  await ctx.state.set(key, { ...s, phase: "row-pending" });
  return { skip: false, values: [[JSON.stringify(invoice)]] };
}

