export default async function ({ key, id }, ctx) {
  const s = await ctx.state.get(key);
  if (s?.phase === "label-pending") throw Error("Inspect Gmail before retry");
  if (s?.phase === "done") return { skip: true, ids: [id] };
  if (s?.phase !== "row-done") throw Error("Invoice row not confirmed");
  await ctx.state.set(key, { ...s, phase: "label-pending" });
  return { skip: false, ids: [id] };
}

